mapper.select:
SELECT id, external_id, content_hash, is_active AS active
FROM job_posting
WHERE source = #{source}

mapper.update:
UPDATE job_posting
SET is_active = 0
WHERE source = #{source}
  AND is_active = 1
  AND external_id NOT IN
  #{eid}

UPDATE job_posting
SET is_active = 0
WHERE source = #{source}
  AND is_active = 1
  AND deadline_on IS NOT NULL
  AND deadline_on < #{today}
